package com.mediconnect.config;
import com.mediconnect.entity.User;import com.mediconnect.repository.UserRepository;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.security.authentication.dao.DaoAuthenticationProvider;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.core.userdetails.UsernameNotFoundException;import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class AuthBeans{
 @Bean UserDetailsService userDetailsService(UserRepository users, @org.springframework.beans.factory.annotation.Value("${app.email-verification-required:false}") boolean emailVerificationRequired){return email->{User u=users.findByEmailIgnoreCase(email).orElseThrow(()->new UsernameNotFoundException("Invalid email or password."));if(emailVerificationRequired&&(!u.isEmailVerified()||u.getAccountStatus()==com.mediconnect.enums.AccountStatus.PENDING_EMAIL_VERIFICATION))throw new org.springframework.security.authentication.LockedException("Verify your email address before signing in.");if(u.getAccountStatus()==com.mediconnect.enums.AccountStatus.DISABLED||(!u.isActive()&&u.getAccountStatus()!=com.mediconnect.enums.AccountStatus.PENDING_APPROVAL&&!( !emailVerificationRequired&&u.getAccountStatus()==com.mediconnect.enums.AccountStatus.PENDING_EMAIL_VERIFICATION)))throw new org.springframework.security.authentication.DisabledException("This account is disabled. Contact the administrator.");if(u.getAccountStatus()==com.mediconnect.enums.AccountStatus.REJECTED||u.getVerificationStatus()==com.mediconnect.enums.VerificationStatus.REJECTED)throw new org.springframework.security.authentication.LockedException("Your account was not approved. Contact the administrator.");return org.springframework.security.core.userdetails.User.withUsername(u.getEmail()).password(u.getPasswordHash()).roles(u.getRole().name()).build();};}
 @Bean DaoAuthenticationProvider authenticationProvider(UserDetailsService service,PasswordEncoder encoder){DaoAuthenticationProvider provider=new DaoAuthenticationProvider();provider.setUserDetailsService(service);provider.setPasswordEncoder(encoder);return provider;}
 @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration configuration)throws Exception{return configuration.getAuthenticationManager();}
}
